import { atom, read, update } from 'claude-code'
import type { AgentInfo, EngineInterface, Register } from 'claude-code'

import type { Dispatch, DispatchKind, DispatchTab, UsageLimit } from '../types'
import { THINKING, describeAction, shellTitle } from './actions'
import {
  ACTIVITY_LABELS,
  CLASSIFIER_HINTS,
  FAILED_MARK_COLOR,
  activityColor,
  activityFromDescription,
  activityTag,
} from './kinds'
import { buildTree, descendantsOf, dropFinishedTrees, liveRootIds } from './tree'
import type { Descendant } from './tree'

const PANE = 'dispatches'
const TITLE = 'Dispatched'
const MAX_ROWS = 100
const OUTER_X = 2
const OUTER_Y = 1
const INNER_X = 1
const ROW_GAP = 0
const ACTION_BACKGROUND = '#3a3a3a'
const WIDTH_SHARE = 2 / 3
const MIN_COLUMNS = 24
const COLUMNS_KEY = 'columns'
/** The footer's name for each rate-limit window; any other kind shows its own name. */
const LIMIT_NAMES: Readonly<Record<string, string>> = { five_hour: 'Session (5h)', seven_day: 'Week', spend_limit: 'Spend' }
const LIMIT_EMPTY_COLOR = '#3a3a3a'
/** A bar turns yellow, then red, as its window fills. */
const limitColor = (percent: number) => (percent >= 90 ? '#ef4444' : percent >= 70 ? '#facc15' : '#22c55e')
/** Catch-all agent types: the card's subtitle names an agent's type only when it is not one of these. */
const GENERIC_TYPES = new Set(['general-purpose', 'claude', 'agent'])

const ENDED = new Set(['completed', 'failed', 'killed', 'done'])

/**
 * The panel's status for an agent the engine lists. A subagent that handed back its
 * result is left `idle`: it could be woken again, but its work is done, so it counts as
 * finished, and a message that wakes it turns it back to running. A teammate that is
 * `idle` is waiting for a message, not done, so it keeps `idle` and stays in Active.
 */
const panelStatus = (agent: AgentInfo) => {
  const isTeammate = agent.teammateId !== undefined || agent.type === 'teammate'
  return agent.status === 'idle' && !isTeammate ? 'done' : agent.status
}

const dispatches = atom({ plugin: 'dispatch-panel', key: 'dispatches' } as const, [])
const now = atom({ plugin: 'dispatch-panel', key: 'now' } as const, 0)
const tab = atom({ plugin: 'dispatch-panel', key: 'tab' } as const, 'active' as DispatchTab)
const isSized = atom({ plugin: 'dispatch-panel', key: 'isSized' } as const, false)
const limits = atom({ plugin: 'dispatch-panel', key: 'limits' } as const, [] as UsageLimit[])
const collapsed = atom({ plugin: 'dispatch-panel', key: 'collapsed' } as const, { agent: false, shell: false } as Record<DispatchKind, boolean>)

/** The docked pane's width as last drawn; the render hook records it, since no `$` call reports it. */
let measuredColumns: number | undefined

const isRunning = (row: Dispatch) => !ENDED.has(row.status)

/** A task-notification row's id and status, in the order the engine writes them. */
const TASK_NOTIFICATION = /<task-id>([^<]+)<\/task-id>[\s\S]*?<status>([^<]+)<\/status>/g
/** The panel's status for each status a task notification reports. */
const NOTIFIED_STATUS: Readonly<Record<string, string>> = { completed: 'done', failed: 'failed', killed: 'killed' }

const firstLine = (text: string) => text.split('\n')[0]?.trim() ?? ''

const upsert = ($: EngineInterface, id: string, patch: (row: Dispatch | undefined) => Dispatch | undefined) =>
  update($, dispatches, list => {
    const rows = list ?? []
    const found = rows.find(row => row.id === id)
    const next = patch(found)
    if (next === undefined) return rows
    if (found === undefined) return [...rows, next].slice(-MAX_ROWS)
    return rows.map(row => (row.id === id ? next : row))
  })

/** Ends each tracked row a task notification in `raw` reports on, with the status it reports. */
const applyNotifications = async ($: EngineInterface, raw: string) => {
  if (!raw.includes('<task-notification>')) return
  const at = await $.clock.now()
  for (const match of raw.matchAll(TASK_NOTIFICATION)) {
    const [, id, status] = match
    if (id === undefined || status === undefined) continue
    const ended = NOTIFIED_STATUS[status] ?? 'done'
    await upsert($, id, row =>
      row === undefined || (!isRunning(row) && row.status !== 'done')
        ? undefined
        : { ...row, status: ended, endedAt: row.endedAt ?? at },
    )
  }
}

const formatCount = (count: number) => {
  if (count < 1000) return `${count}`
  if (count < 1_000_000) return `${(count / 1000).toFixed(1)}k`
  return `${(count / 1_000_000).toFixed(2)}M`
}

const storedColumns = async ($: EngineInterface) => {
  const stored = await $.store.get(COLUMNS_KEY)
  return typeof stored === 'number' ? stored : undefined
}

const openPane = async ($: EngineInterface) => {
  const columns = await storedColumns($)
  return $.ui.open({ id: PANE, title: TITLE, ...(columns === undefined ? {} : { columns }) })
}

/**
 * Narrows the dock once per session to the remembered width, or to two thirds of the
 * width it was first drawn at, and remembers that width for later sessions.
 * The dock treats it as a request: a width the person dragged the dock to wins.
 */
const fitWidth = async ($: EngineInterface) => {
  if (measuredColumns === undefined || (await read($, isSized)) === true) return
  const panes = await $.ui.panes()
  if (!panes.some(pane => pane.id === PANE && pane.isPlaced)) return
  const columns = (await storedColumns($)) ?? Math.max(MIN_COLUMNS, Math.round(measuredColumns * WIDTH_SHARE))
  await $.store.set(COLUMNS_KEY, columns)
  await update($, isSized, () => true)
  await $.ui.open({ id: PANE, title: TITLE, columns })
}

const formatDuration = (ms: number) => {
  const seconds = Math.max(0, Math.floor(ms / 1000))
  const h = Math.floor(seconds / 3600)
  const m = Math.floor((seconds % 3600) / 60)
  const s = seconds % 60
  if (h > 0) return `${h}h${String(m).padStart(2, '0')}m`
  if (m > 0) return `${m}m${String(s).padStart(2, '0')}s`
  return `${s}s`
}

/** Time left until an ISO timestamp, as `2h14m` or `3d04h`; empty when unknown or past. */
const formatUntil = (iso: string | undefined, at: number) => {
  const resets = iso === undefined ? Number.NaN : Date.parse(iso)
  if (Number.isNaN(resets) || resets <= at) return ''
  const minutes = Math.ceil((resets - at) / 60_000)
  const d = Math.floor(minutes / 1440)
  const h = Math.floor((minutes % 1440) / 60)
  const m = minutes % 60
  if (d > 0) return `${d}d${String(h).padStart(2, '0')}h`
  if (h > 0) return `${h}h${String(m).padStart(2, '0')}m`
  return `${m}m`
}

/**
 * Reads the account's rate-limit windows, as the status line has them. The plain
 * `$.session.usage()` call costs nothing; the atom is written only when a window moved.
 */
const syncLimits = async ($: EngineInterface) => {
  const { rateLimits } = await $.session.usage()
  const fresh = rateLimits.map(({ kind, percentUsed, resetsAt }) => ({ kind, percentUsed, resetsAt }))
  const known = (await read($, limits)) ?? []
  if (JSON.stringify(fresh) !== JSON.stringify(known)) await update($, limits, () => fresh)
}

const statusMark = (status: string) => {
  if (status === 'failed') return '✗'
  if (status === 'killed') return '■'
  if (status === 'idle' || status === 'waiting') return '◌'
  if (ENDED.has(status)) return '✓'
  return '●'
}

/** Reconciles tracked agents with the engine's own list, and finds any the spawn hook missed. */
const syncAgents = async ($: EngineInterface, at: number) => {
  const agents = await $.agent.list()
  for (const agent of agents) {
    const status = panelStatus(agent)
    await upsert($, agent.id, row => {
      if (row === undefined) {
        if (ENDED.has(status)) return undefined
        return {
          id: agent.id,
          kind: 'agent',
          label: agent.type,
          purpose: agent.description,
          status,
          startedAt: at,
          parentId: agent.parentId,
          ...(activityFromDescription(agent.description) === undefined
            ? {}
            : { activity: activityFromDescription(agent.description), isClassified: true }),
        }
      }
      const parentId = row.parentId ?? agent.parentId
      if (row.status === status && row.parentId === parentId) return undefined
      const hasEnded = ENDED.has(status)
      return {
        ...row,
        status,
        parentId,
        endedAt: hasEnded ? (row.endedAt ?? at) : undefined,
      }
    })
  }
  // An agent the engine no longer lists is over, whatever its row last said:
  // without this, a row whose final status was never seen stays active forever.
  const listed = new Set(agents.map(agent => agent.id))
  await update($, dispatches, list =>
    (list ?? []).map(row =>
      row.kind === 'agent' && isRunning(row) && !listed.has(row.id) ? { ...row, status: 'done', endedAt: at } : row,
    ),
  )
}

/**
 * Ends the running shells of an agent that has ended. Such a shell sends its completion
 * notice to its owner's queue, which nobody reads once the owner is done or stopped, so
 * without this its row stays active forever. A stopped owner's shells show as stopped.
 */
const endOrphanShells = async ($: EngineInterface, at: number) =>
  update($, dispatches, list => {
    const rows = list ?? []
    const byId = new Map(rows.map(row => [row.id, row]))
    return rows.map(row => {
      const owner = row.parentId === undefined ? undefined : byId.get(row.parentId)
      if (row.kind !== 'shell' || !isRunning(row) || owner === undefined || isRunning(owner)) return row
      return { ...row, status: owner.status === 'killed' ? 'killed' : 'done', endedAt: owner.endedAt ?? at }
    })
  })

/**
 * Classifies one agent's activity per tick, outside any hook's dispatch, so a slow
 * model call never holds up a spawn. A failed call settles on 'something else'.
 */
const classifyNext = async ($: EngineInterface) => {
  const list = (await read($, dispatches)) ?? []
  const row = list.find(one => one.kind === 'agent' && one.isClassified !== true)
  if (row === undefined) return
  await upsert($, row.id, found => (found === undefined ? undefined : { ...found, isClassified: true }))
  const text = [`agent type: ${row.label}`, `task: ${row.purpose}`, row.brief ? `prompt: ${row.brief}` : '', CLASSIFIER_HINTS]
    .filter(Boolean)
    .join('\n')
  let activity: string | undefined
  try {
    activity = await $.model.classify(text, ACTIVITY_LABELS)
  } catch {
    activity = undefined
  }
  await upsert($, row.id, found =>
    found === undefined ? undefined : { ...found, activity: activity ?? 'something else' },
  )
}

const tick = async ($: EngineInterface) => {
  const at = await $.clock.now()
  await syncAgents($, at)
  await endOrphanShells($, at)
  await classifyNext($)
  await fitWidth($)
  await syncLimits($).catch(() => undefined)
  const list = (await read($, dispatches)) ?? []
  if (list.some(isRunning)) await update($, now, () => at)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'dispatches',
      description:
        'Show dispatched agents and shells in a side panel (`active`, `finished`, `clear` to drop finished rows, `clear all` to drop every row, `width <columns>` to resize)',
      argumentHint: '[active|finished|clear|clear all|width <columns>]',
    })
    const startedAt = await $.clock.now()
    await update($, now, () => startedAt)
    $.clock.every(1000, () => void tick($))
    void openPane($)

    return next(e)
  })

  on('command.run', { command: 'dispatches' }, async ($, e) => {
    const arg = e.args.trim()
    if (arg === 'active' || arg === 'finished') {
      await update($, tab, () => arg)
      await openPane($)
      return { text: `Dispatch panel opened on ${arg}.` }
    }
    const width = /^width\s+(\d+)$/.exec(arg)
    if (width?.[1] !== undefined) {
      const columns = Math.max(MIN_COLUMNS, Number(width[1]))
      await $.store.set(COLUMNS_KEY, columns)
      await update($, isSized, () => true)
      await $.ui.open({ id: PANE, title: TITLE, columns })
      return { text: `Dispatch panel width set to ${columns} columns.` }
    }
    if (arg === 'clear all') {
      await update($, dispatches, () => [])
      return { text: 'Cleared every dispatch, active ones included.' }
    }
    if (arg === 'clear') {
      await update($, dispatches, list => dropFinishedTrees(list ?? [], isRunning))
      return { text: 'Cleared finished dispatches.' }
    }
    await openPane($)
    return { text: 'Dispatch panel opened.' }
  })

  on('agent.spawn', async ($, e, next) => {
    const startedAt = await $.clock.now()
    const spawned = await next(e)
    if (spawned.agentId !== undefined) {
      const agentId = spawned.agentId
      // A description that names its activity outright colours the row at once.
      const signalled = activityFromDescription(e.description)
      await upsert($, agentId, row => ({
        id: agentId,
        kind: 'agent',
        label: e.subagentType || 'agent',
        purpose: e.description || firstLine(e.prompt),
        brief: e.prompt.slice(0, 600),
        activity: row?.activity ?? signalled,
        isClassified: row?.isClassified ?? (signalled === undefined ? undefined : true),
        action: row?.action ?? 'starting',
        status: row?.status ?? 'running',
        startedAt: row?.startedAt ?? startedAt,
        endedAt: row?.endedAt,
        inputTokens: row?.inputTokens,
        outputTokens: row?.outputTokens,
        parentId: e.parentAgentId ?? row?.parentId,
      }))
    }
    return spawned
  })

  on('turn.step', async function* ($, e, next) {
    const step = yield* next(e)
    const agentId = e.agentId
    const usage = step.usage
    if (agentId !== undefined && usage !== null) {
      const inputTokens = usage.input_tokens + usage.cache_read_input_tokens + usage.cache_creation_input_tokens
      await upsert($, agentId, row =>
        row === undefined
          ? undefined
          : {
              ...row,
              inputTokens: (row.inputTokens ?? 0) + inputTokens,
              outputTokens: (row.outputTokens ?? 0) + usage.output_tokens,
            },
      )
    }
    return step
  })

  /** Each tool call an agent makes is its current action, until the call ends and it thinks again. */
  on('tool.call', async ($, e, next) => {
    const agentId = e.agentId
    if (agentId === undefined) return next(e)
    const action = describeAction(String(e.tool), e as unknown as Record<string, unknown>)
    const setAction = (label: string) =>
      upsert($, agentId, row => (row === undefined || !isRunning(row) ? undefined : { ...row, action: label }))
    await setAction(action)
    const ran = await next(e)
    await setAction(THINKING)
    return ran
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    if (e.tool !== 'Bash') return next(e)
    const startedAt = await $.clock.now()
    const ran = await next(e)
    if (ran.deny !== undefined || ran.isError) return ran
    const taskId = ran.result.backgroundTaskId
    if (taskId !== undefined) {
      const purpose = e.description || shellTitle(e.command)
      await upsert($, taskId, row =>
        row ?? { id: taskId, kind: 'shell', label: 'bash', purpose, status: 'running', startedAt, parentId: e.agentId },
      )
    }
    return ran
  })

  on('tool.call', { tool: 'TaskStop' }, async ($, e, next) => {
    if (e.tool !== 'TaskStop') return next(e)
    const ran = await next(e)
    const taskId = e.task_id ?? e.shell_id
    if (taskId !== undefined && ran.deny === undefined && !ran.isError) {
      const at = await $.clock.now()
      await upsert($, taskId, row =>
        row === undefined || !isRunning(row) ? undefined : { ...row, status: 'killed', endedAt: at },
      )
    }
    return ran
  })

  /**
   * Every finished background task sends a notification to its owner, a subagent
   * included, carrying the task's id and final status. It is the one signal that
   * reaches the panel for a shell a subagent started.
   *
   * It reaches the session twice: `session.receive` when it is queued, the moment
   * the task ends, and `session.append` once it becomes a row of the conversation.
   * Between the person's turns the main thread's notifications wait in the queue
   * until the next turn, and some are folded into that turn without a row of their
   * own, so the queue is where a shell that ends between turns is seen.
   */
  on('session.receive', async ($, e, next) => {
    await applyNotifications($, e.text)
    return next(e)
  })

  on('session.append', async ($, e, next) => {
    const appended = await next(e)
    await applyNotifications($, JSON.stringify(e.message.content))
    return appended
  })

  /** At each stop the engine lists the background work still in flight: any shell missing from it has finished. */
  on('classic.Stop', async ($, e, next) => {
    const inFlight = e.background_tasks ?? []
    const at = await $.clock.now()
    const liveShells = new Set(inFlight.filter(task => task.type === 'shell').map(task => task.id))
    await update($, dispatches, list =>
      (list ?? []).map(row =>
        row.kind === 'shell' && isRunning(row) && !liveShells.has(row.id)
          ? { ...row, status: 'done', endedAt: at }
          : row,
      ),
    )
    for (const task of inFlight) {
      if (task.type !== 'shell') continue
      await upsert($, task.id, row =>
        row ?? {
          id: task.id,
          kind: 'shell',
          label: 'bash',
          purpose: task.description || shellTitle(task.command ?? ''),
          status: 'running',
          startedAt: at,
        },
      )
    }
    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Button, Text } = $.ui.resolve(e)
    const list = (await read($, dispatches)) ?? []
    const at = (await read($, now)) ?? 0
    const shownTab = (await read($, tab)) ?? 'active'
    const width = Math.max(10, e.props.bodyColumns)
    // The card's inside: the panel's width less its side padding, the card's border and its padding.
    const stripColumns = Math.max(4, width - 2 * OUTER_X - 2 - 2 * INNER_X)
    if (e.props.placement === 'dock') measuredColumns = e.props.bodyColumns
    // One card per top-level row; what a dispatched agent started is listed inside its card,
    // and the whole tree stays in Active while any row in it runs.
    const tree = buildTree(list)
    const live = liveRootIds(list, isRunning)
    const roots = list.filter(row => tree.rootIdOf(row) === row.id)
    const active = roots.filter(row => live.has(row.id))
    const finished = roots.filter(row => !live.has(row.id)).reverse()
    const shown = shownTab === 'active' ? active : finished
    const showTab = (next: DispatchTab) => () => void update($, tab, () => next)

    // Terminal spacing is in cells, not pixels: a cell is about 10px wide and 20px tall,
    // so OUTER (about 20px) is 2 columns or 1 row, and INNER (about 10px) is 1 column.
    // Half a row does not exist, so the gap between rows (about 10px asked) is 0 rows.
    const elapsedOf = (row: Dispatch) => (row.endedAt ?? Math.max(at, row.startedAt)) - row.startedAt
    const markColorOf = (row: Dispatch) => (row.status === 'failed' ? FAILED_MARK_COLOR : activityColor(row))

    /** One line inside a card for an agent or shell the card's agent started, indented by depth. */
    const childLine = ({ row, depth, isLast }: Descendant) => {
      const running = isRunning(row)
      const color = activityColor(row)
      const tag = row.kind === 'shell' ? 'shell' : activityTag(row)
      return (
        <Box key={row.id} flexDirection="row" gap={1}>
          {/* Branch, mark and title in one text, so their spacing never collapses as the title truncates. */}
          <Box flexShrink={1}>
            <Text wrap="truncate-end">
              <Text dimColor>{`${'  '.repeat(depth)}${isLast ? '└' : '├'} `}</Text>
              <Text color={markColorOf(row)} dimColor={!running}>
                {statusMark(row.status)}
              </Text>
              <Text color={color} dimColor={!running}>{` ${row.purpose || row.label}`}</Text>
            </Text>
          </Box>
          {tag !== undefined && (
            <Box flexShrink={0}>
              <Text color={color} dimColor>{`[${tag}]`}</Text>
            </Box>
          )}
          <Box flexGrow={1} />
          <Box flexShrink={0}>
            <Text dimColor={!running}>{formatDuration(elapsedOf(row))}</Text>
          </Box>
        </Box>
      )
    }

    const card = (row: Dispatch) => {
      const running = isRunning(row)
      const isLive = live.has(row.id)
      const elapsed = elapsedOf(row)
      const color = activityColor(row)
      const tag = activityTag(row)
      const markColor = markColorOf(row)
      const descendants = descendantsOf(tree, row.id)
      const subInput = descendants.reduce((sum, { row: child }) => sum + (child.inputTokens ?? 0), 0)
      const subOutput = descendants.reduce((sum, { row: child }) => sum + (child.outputTokens ?? 0), 0)
      return (
        <Box
          key={row.id}
          flexDirection="column"
          borderStyle="round"
          borderColor={color}
          borderDimColor={!isLive}
          paddingX={INNER_X}
          marginBottom={ROW_GAP}
        >
          <Box flexDirection="row" gap={1}>
            <Text color={markColor} dimColor={!running}>
              {statusMark(row.status)}
            </Text>
            <Box flexShrink={1}>
              <Text color={color} bold={running} dimColor={!running} wrap="truncate-end">
                {row.purpose || row.label}
              </Text>
            </Box>
            {tag !== undefined && (
              <Box flexShrink={0}>
                <Text color={color} dimColor={!running}>{`[${tag}]`}</Text>
              </Box>
            )}
            <Box flexGrow={1} />
            <Box flexShrink={0}>
              <Text dimColor={!running}>{formatDuration(elapsed)}</Text>
            </Box>
          </Box>
          {row.kind === 'agent' && !GENERIC_TYPES.has(row.label) && (
            <Text dimColor italic wrap="truncate-end">
              {row.label}
            </Text>
          )}
          {row.kind === 'agent' && (
            <Text dimColor wrap="truncate-end">
              {`in ${formatCount(row.inputTokens ?? 0)} · out ${formatCount(row.outputTokens ?? 0)}`}
              {subInput + subOutput > 0 ? ` · sub in ${formatCount(subInput)} · out ${formatCount(subOutput)}` : ''}
            </Text>
      )}
          {descendants.map(childLine)}
          {row.kind === 'agent' && running && row.action !== undefined && (
            // A row cannot be split, so the strip's top and bottom edges are half blocks:
            // they read as half a row of space above and below a slightly taller strip.
            <Box flexDirection="column" width={stripColumns}>
              <Text color={ACTION_BACKGROUND}>{'▄'.repeat(stripColumns)}</Text>
              <Box backgroundColor={ACTION_BACKGROUND} paddingX={INNER_X}>
                <Text wrap="truncate-end">
                  <Text color={color}>▸ </Text>
                  {row.action}
                </Text>
              </Box>
              <Text color={ACTION_BACKGROUND}>{'▀'.repeat(stripColumns)}</Text>
            </Box>
      )}
        </Box>
      )
    }

    const folded = (await read($, collapsed)) ?? { agent: false, shell: false }
    const sections = (
      [
        { kind: 'agent', title: 'Agents', rows: shown.filter(row => row.kind === 'agent') },
        { kind: 'shell', title: 'Shells', rows: shown.filter(row => row.kind === 'shell') },
      ] as const
    ).filter(section => section.rows.length > 0)
    const toggle = (kind: DispatchKind) => () =>
      void update($, collapsed, state => {
        const current = state ?? { agent: false, shell: false }
        return { ...current, [kind]: !current[kind] }
      })

    // The footer: one bar per rate-limit window of the account, pinned to the pane's bottom
    // while the rows fit, and following the rows when they scroll.
    const windows = (await read($, limits)) ?? []
    const footerColumns = Math.max(4, width - 2 * OUTER_X)
    const limitBar = (limit: UsageLimit) => {
      const percent = Math.max(0, Math.min(100, limit.percentUsed))
      const filled = Math.round((percent / 100) * footerColumns)
      const resets = formatUntil(limit.resetsAt, at)
      return (
        <Box key={limit.kind} flexDirection="column">
          <Box flexDirection="row" gap={1}>
            <Box flexShrink={1}>
              <Text dimColor wrap="truncate-end">
                {LIMIT_NAMES[limit.kind] ?? limit.kind.replace(/_/g, ' ')}
              </Text>
            </Box>
            <Box flexGrow={1} />
            <Text color={limitColor(percent)}>{`${Math.round(limit.percentUsed)}%`}</Text>
            {resets !== '' && <Text dimColor>{`· resets in ${resets}`}</Text>}
          </Box>
          <Text>
            <Text color={limitColor(percent)}>{'█'.repeat(filled)}</Text>
            <Text color={LIMIT_EMPTY_COLOR}>{'█'.repeat(footerColumns - filled)}</Text>
          </Text>
        </Box>
      )
    }

    return (
      <Box
        flexDirection="column"
        width={width}
        minHeight={e.props.scroll.bodyRows}
        paddingX={OUTER_X}
        paddingY={OUTER_Y}
      >
        <Box flexDirection="row" gap={OUTER_X} marginBottom={OUTER_Y}>
          <Button
            key="tab-active"
            hotkey="a"
            variant={shownTab === 'active' ? 'primary' : 'secondary'}
            onPress={showTab('active')}
          >
            Active ({active.length})
          </Button>
          <Button
            key="tab-finished"
            hotkey="f"
            variant={shownTab === 'finished' ? 'primary' : 'secondary'}
            onPress={showTab('finished')}
          >
            Finished ({finished.length})
          </Button>
          {shownTab === 'finished' && finished.length > 0 && (
            <Button key="clear" plain dimColor onPress={() => void update($, dispatches, rows => dropFinishedTrees(rows ?? [], isRunning))}>
              clear
            </Button>
          )}
        </Box>
        {shown.length === 0 && (
          <Text dimColor>{shownTab === 'active' ? 'Nothing running.' : 'Nothing finished yet.'}</Text>
        )}
        {sections.map(section => (
          <Box key={section.title} flexDirection="column" marginBottom={OUTER_Y}>
            <Button key={`section-${section.kind}`} plain onPress={toggle(section.kind)}>
              <Text dimColor bold>
                {folded[section.kind] ? '▸' : '▾'} {section.title} ({section.rows.length})
              </Text>
            </Button>
            {!folded[section.kind] && section.rows.map(card)}
          </Box>
        ))}
        {windows.length > 0 && <Box flexGrow={1} />}
        {windows.length > 0 && (
          <Box flexDirection="column">
            <Text dimColor>{'─'.repeat(footerColumns)}</Text>
            {windows.map(limitBar)}
          </Box>
        )}
      </Box>
    )
  })
}

